"""Optional natural-language commentary on trade decisions, generated by Claude.

Commentary is advisory text only. It is generated AFTER the deterministic
decision and risk checks, is never fed back into execution, and is only given
the structured facts the engine computed. It never receives keys, wallet data
or account credentials.
"""
from __future__ import annotations

import asyncio
import json

from .config import get_settings
from .logging import get_logger

log = get_logger("atlas.commentary")

SYSTEM = (
    "You are the analysis narrator for an automated crypto trading system. You receive a JSON object with facts "
    "computed by deterministic code: strategy signal, indicator values, risk checks and the final decision. "
    "Write 2-4 plain sentences explaining the decision for a trader. Rules: use ONLY numbers and facts present in "
    "the JSON; never invent prices, indicators, news or outcomes; do not predict profit; do not recommend overriding "
    "risk controls; mention the main risk. If the data is insufficient, say so."
)


class Commentator:
    def __init__(self):
        s = get_settings()
        self.model = s.ai_commentary_model
        self.enabled = bool(s.anthropic_api_key) and s.ai_commentary_enabled
        self._client = None
        self.last_error: str | None = None
        if self.enabled:
            import anthropic

            self._client = anthropic.AsyncAnthropic(api_key=s.anthropic_api_key.get_secret_value(), max_retries=2, timeout=60)
        self._sem = asyncio.Semaphore(2)

    def status(self) -> dict:
        if not self.enabled:
            return {"status": "unconfigured", "detail": "set ANTHROPIC_API_KEY to enable AI commentary"}
        return {"status": "degraded" if self.last_error else "ok", "model": self.model, "last_error": self.last_error}

    async def explain(self, facts: dict) -> str | None:
        if not self.enabled or self._client is None:
            return None
        import anthropic

        async with self._sem:
            try:
                resp = await self._client.beta.messages.create(
                    model=self.model,
                    max_tokens=1024,
                    system=SYSTEM,
                    output_config={"effort": "low"},
                    betas=["server-side-fallback-2026-07-01"],
                    fallbacks="default",
                    messages=[{"role": "user", "content": json.dumps(facts, default=str)[:20_000]}],
                )
            except anthropic.RateLimitError:
                self.last_error = "rate limited"
                return None
            except anthropic.APIStatusError as e:
                self.last_error = f"API error {e.status_code}"
                return None
            except anthropic.APIConnectionError:
                self.last_error = "connection error"
                return None
            if resp.stop_reason == "refusal":
                self.last_error = "model declined"
                return None
            self.last_error = None
            text = "".join(getattr(b, "text", "") for b in resp.content if getattr(b, "type", "") == "text").strip()
            return text[:2000] or None
